// MODE: 'create' makes the throwaway key, 'inspect' reads it back, 'delete' removes it.
const MODE = 'create';
const PID = '14240418673f52ae29a007.74392007'; // Mobitrace
const KEY = 'zz::claude::automation_probe_070926';
const EN = 'Your parcel is on its way and should arrive within two working days.';
const B = 'https://api.lokalise.com/api2/projects/' + PID;
if (MODE === 'create') {
  return [{ json: { mode: MODE, method: 'POST', url: B + '/keys', body: { keys: [ { key_name: KEY, platforms: ['web'], tags: ['zz_temp_probe'], translations: [ { language_iso: 'en', translation: EN } ] } ] } } }];
}
if (MODE === 'inspect') {
  return [{ json: { mode: MODE, method: 'GET', url: B + '/keys?filter_keys=' + encodeURIComponent(KEY) + '&include_translations=1&limit=10', body: null } }];
}
return [{ json: { mode: MODE, method: 'GET', url: B + '/keys?filter_keys=' + encodeURIComponent(KEY) + '&limit=10', body: null } }];

const meta = $('Config').first().json;
const r = $input.first().json || {};
const b = r.body || {};
const rows = [];
for (const k of (b.keys || [])) {
  const per = [];
  for (const t of (k.translations || [])) {
    const s = t.translation == null ? '' : String(t.translation);
    per.push({ iso: t.language_iso, text: s, fuzzy: !!t.is_fuzzy, reviewed: !!t.is_reviewed, cts: (t.custom_translation_statuses || []).map(function (x) { return x.title; }).join(',') });
  }
  rows.push({ key_id: k.key_id, name: (k.key_name || {}).web, filled: per.filter(function (x) { return x.text.trim() && x.iso !== 'en'; }).length, translations: per });
}
return [{ json: { mode: meta.mode, status: r.statusCode, errors: b.errors || null, keys: rows, raw: rows.length ? null : JSON.stringify(b).slice(0, 400) } }];
